```mermaid
sequenceDiagram
    participant User as User
    participant Timeline as Timeline
    participant PM as PluginManager
    participant Plugin as Plugin Instance

    User->>Timeline: usePlugin(plugin)
    Timeline->>PM: loadPlugin(plugin)
